export const trust=()=>`<div class="container trust-strip" aria-label="Преимущества ArtBalkon"><div><strong>15 лет</strong><span>опыта команды</span></div><div><strong>1 250+</strong><span>готовых проектов</span></div><div><strong>до 5 лет</strong><span>гарантии по договору</span></div></div>`;
const beforeAfterAsset=file=>file.includes('/')?file:`before-after/${file}`;
const expandServiceBeforeAfter=(service,items,min=12)=>{
 const result=[],seen=new Set(),add=project=>{
  const key=`${beforeAfterAsset(project.before)}|${beforeAfterAsset(project.after)}`;
  if(seen.has(key))return;
  seen.add(key);
  result.push(project);
 };
 items.forEach(add);
 const offset=[...service.slug].reduce((sum,char)=>sum+char.charCodeAt(0),0)%beforeAfterProjects.length;
 for(let index=0;index<beforeAfterProjects.length&&result.length<min;index++)add(beforeAfterProjects[(offset+index)%beforeAfterProjects.length]);
 return result.slice(0,min);
};
const beforeAfterSection=(items=beforeAfterProjects,{serviceTitle=''}={})=>{
 const cards=items.map(p=>{const before=beforeAfterAsset(p.before),after=beforeAfterAsset(p.after),beforeAlt=p.visualized?'до работ, тематическая визуализация':p.beforeReal?'до работ ArtBalkon':'до ремонта, визуальная реконструкция',afterAlt=p.visualized?'после работ, тематическая визуализация':'после работ ArtBalkon';return `<article class="before-after-card reveal"><button class="before-after-compare" type="button" data-comparison data-title="${esc(p.title)}" data-description="${esc(p.description)}" data-before="assets/${before}" data-after="assets/${after}" data-before-real="${Boolean(p.beforeReal)}" data-visualized="${Boolean(p.visualized)}" aria-label="Сравнить до и после: ${esc(p.title)}"><span class="before-after-preview"><span><img src="/assets/${before}" width="960" height="1280" loading="lazy" decoding="async" alt="${esc(p.title)} — ${beforeAlt}"><b>До</b></span><span><img src="/assets/${after}" width="960" height="1280" loading="lazy" decoding="async" alt="${esc(p.title)} — ${afterAlt}"><b>После</b></span></span><span class="before-after-title">${esc(p.title)}</span></button><button class="before-after-lead" type="button" data-application data-project="${esc(p.title)}">Хочу также</button></article>`;}).join('');
 return `<section class="soft-section before-after-section" id="before-after"><div class="section container"><div class="section-heading"><h2>До и После</h2>${serviceTitle?`<p class="section-description">Примеры по услуге «${esc(serviceTitle)}»</p>`:''}</div><div class="before-after-grid ${items.length<3?'compact':''}">${cards}</div></div><dialog class="comparison-modal" id="comparison-modal" aria-labelledby="comparison-title"><div class="comparison-modal-shell"><div class="comparison-modal-head"><div><p class="eyebrow">ПРЕОБРАЖЕНИЕ БАЛКОНА</p><h2 id="comparison-title"></h2><p id="comparison-description"></p></div><button class="comparison-close" type="button" aria-label="Закрыть сравнение">×</button></div><div class="comparison-modal-grid"><figure><span id="comparison-before-label">До · реконструкция</span><img id="comparison-before" width="960" height="1280" alt="Объект до работ"></figure><figure><span id="comparison-after-label">После · ArtBalkon</span><img id="comparison-after" width="960" height="1280" alt="Объект после работ"></figure></div></div></dialog><dialog class="application-modal" id="application-modal" aria-labelledby="application-title"><div class="application-modal-shell"><button class="application-close" type="button" aria-label="Закрыть форму">×</button><div class="application-modal-copy"><p class="eyebrow">ПОНРАВИЛСЯ ПРОЕКТ?</p><h2 id="application-title">Оставить заявку</h2><p>Оставьте контакты — обсудим похожее преображение для вашего балкона.</p><strong id="application-project"></strong></div><form class="contact-form application-form" data-lead-form="transformation" novalidate><input type="hidden" name="project">${contactFields('application-consent')}<p class="form-error" role="alert"></p><button class="button" type="submit">Отправить заявку ${buttonArrow}</button><p class="contact-note">Перезвоним и уточним детали проекта.</p></form></div></dialog></section>`;
};
