const finishingStylesSection=()=>`<section class="section container finishing-styles" id="finishing-styles" data-finishing-styles aria-labelledby="finishing-styles-title"><div class="section-heading"><div><h2 id="finishing-styles-title">Варианты отделки<br>балконов и лоджий</h2></div><p class="section-description">Показываем разные направления и подбираем материалы под ваш вкус, задачи и бюджет.</p></div><div class="finishing-style-tabs" role="tablist" aria-label="Стили отделки">${finishingStyles.map((style,index)=>`<button type="button" role="tab" id="finishing-tab-${style.id}" aria-controls="finishing-panel-${style.id}" aria-selected="${index===0?'true':'false'}" tabindex="${index===0?'0':'-1'}" data-finishing-tab="${style.id}">${style.label}</button>`).join('')}</div><div class="finishing-style-panels">${finishingStyles.map((style,index)=>`<article class="finishing-style-panel" id="finishing-panel-${style.id}" role="tabpanel" aria-labelledby="finishing-tab-${style.id}" data-finishing-panel="${style.id}" ${index===0?'':'hidden'}><div class="finishing-style-copy"><p class="eyebrow">СТИЛЬ ОТДЕЛКИ</p><h3>${style.title}</h3><p>${style.text}</p><p>${style.note}</p>${button('Подобрать отделку')}</div><div class="finishing-style-gallery">${style.images.map((image,imageIndex)=>`<figure><img src="/assets/${image}" width="960" height="640" loading="lazy" decoding="async" alt="${style.title} — дизайн-концепт отделки балкона${imageIndex+1}"></figure>`).join('')}</div></article>`).join('')}</div></section>`;
export function projectCards(limit=3){return `<div class="project-grid">${projects.slice(0,limit).map(p=>`<article class="project-card"><a class="project-image" data-event="portfolio_open" data-project="${p.slug}" href="/nashi-raboty/${p.slug}/">${pic(p.image,p.alt)}<span class="image-tag">${p.type}</span><span class="image-arrow" aria-hidden="true">↗</span></a><p class="project-location">${p.location}</p><h3><a href="/nashi-raboty/${p.slug}/" data-event="portfolio_open" data-project="${p.slug}">${p.title}</a></h3><p class="project-materials">${p.materials.slice(0,2).join(' · ')}</p><a class="text-link" data-event="portfolio_open" data-project="${p.slug}" href="/nashi-raboty/${p.slug}/">Смотреть проект ${arrow}</a></article>`).join('')}</div>`;}
