const sourceServiceDetailsSection=s=>{const detail=sourceServiceDetails[s.slug];if(!detail)return '';return `<section class="section container source-service-details" aria-labelledby="source-service-${esc(s.slug)}"><div class="section-heading"><div><p class="eyebrow">ПОДРОБНО ОБ УСЛУГЕ</p><h2 id="source-service-${esc(s.slug)}">${esc(detail.title)}</h2></div><p class="section-description">${esc(detail.intro)}</p></div><div class="source-service-details-grid">${detail.items.map(([title,text],index)=>`<article><span>${String(index+1).padStart(2,'0')}</span><h3>${esc(title)}</h3><p>${esc(text)}</p></article>`).join('')}</div><div class="source-service-details-note"><p>${esc(detail.note)}</p><p>Цены «от» — ориентиры для планирования. Точную стоимость зафиксируем после замера, выбора материалов и согласования комплектации.</p></div><div class="section-cta">${button('Получить точный расчёт')}</div></section>`;};
const serviceSeoSection=s=>{const seo=serviceSeo[s.slug];if(!seo)return '';return `<section class="section container service-seo-intro"><div><p class="eyebrow">${esc(seo.eyebrow)}</p><h2>${esc(seo.title)}</h2>${seo.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${button('Получить расчёт')}</div><figure><img src="/assets/${esc(seo.concept[0])}" width="960" height="640" loading="lazy" decoding="async" alt="${esc(seo.concept[1])}"><figcaption>${esc(seo.concept[2])} · дизайн-концепт</figcaption></figure></section><section class="soft-section"><div class="section container service-scope"><div class="section-heading"><div><p class="eyebrow">СОСТАВ РАБОТ</p><h2>Что учитываем<br>в проекте</h2></div><p class="section-description">Состав и материалы уточняем после осмотра и точного замера объекта.</p></div><div class="service-scope-grid">${seo.scope.map(([title,text])=>`<article><h3>${esc(title)}</h3><p>${esc(text)}</p></article>`).join('')}</div></div></section><section class="section container service-photo-section"><div class="section-heading"><div><p class="eyebrow">ПРИМЕРЫ РАБОТ</p><h2>Как это выглядит<br>на реальных объектах</h2></div><a class="text-link" href="/nashi-raboty/">Все проекты ${arrow}</a></div><div class="service-photo-grid">${seo.photos.map(([name,alt,caption])=>`<figure>${pic(name,alt)}<figcaption>${esc(caption)}</figcaption></figure>`).join('')}</div></section><section class="section container service-process"><div class="section-heading"><div><p class="eyebrow">ПОЭТАПНО И ПОНЯТНО</p><h2>Как проходит работа</h2></div></div><ol>${seo.steps.map(([title,text])=>`<li><h3>${esc(title)}</h3><p>${esc(text)}</p></li>`).join('')}</ol><div class="section-cta">${button('Начать с бесплатного замера')}</div></section><section class="soft-section"><div class="section container service-page-faq"><div><p class="eyebrow">ВАЖНО ЗНАТЬ</p><h2>Ответы на вопросы</h2><p>Коротко отвечаем на вопросы, которые возникают до замера и расчёта.</p></div><div>${seo.faq.map(([q,a])=>`<details><summary>${esc(q)}<span aria-hidden="true">+</span></summary><p>${esc(a)}</p></details>`).join('')}</div></div></section>`;};
export const consent=id=>`<label class="consent" for="${id}"><input id="${id}" name="consent" type="checkbox" required><span>Соглашаюсь на <a href="/consent/" target="_blank">обработку персональных данных</a> и ознакомлен(а) с <a href="/privacy/" target="_blank">политикой конфиденциальности</a>.</span></label>`;
export const contactFields=id=>`<div class="field-row"><label class="field">Ваше имя<input name="name" autocomplete="given-name" maxlength="70" placeholder="Как к вам обращаться" required></label><label class="field">Телефон<input name="phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="22" placeholder="+7 (___) ___-__-__" required></label></div><div class="honeypot" aria-hidden="true"><label>Сайт<input name="website" tabindex="-1" autocomplete="off"></label></div>${consent(id)}`;
