export function contact(){
 const finalCta=`<section class="container final-section final-visual-cta" aria-labelledby="final-cta-title"><div class="final-copy"><p class="eyebrow">БЕСПЛАТНЫЙ ЗАМЕР</p><h2 id="final-cta-title">Оставьте заявку<br>на замер</h2><p>Расскажите, каким хотите видеть свой балкон. Уточним детали, ответим на вопросы и подготовим предварительный расчёт.</p><div class="final-links"><a href="tel:${company.tel}" class="big-phone" data-event="phone_click">${company.phone}</a><a class="messenger" href="${company.telegram}" target="_blank" rel="noopener" data-event="telegram_click">Написать в Telegram ${arrow}</a></div></div><form class="contact-form final-lead-form" data-lead-form="contact" novalidate><h3>Обсудим ваш проект</h3><p class="final-form-intro">Оставьте контакты — перезвоним и договоримся об удобном времени замера.</p>${contactFields('contact-consent')}<p class="form-error" role="alert"></p><button class="button" type="submit">Отправить заявку ${buttonArrow}</button><p class="contact-note">Ежедневно, с 9:00 до 21:00.</p></form></section>`;
 const contactLocation=`<section class="container contact-location" id="contacts" aria-labelledby="office-title"><div class="contact-location-copy"><p class="eyebrow">ОФИС ARTBALKON</p><h2 id="office-title">Будем рады<br>встрече с вами</h2><p class="contact-location-intro">Обсудим ваш балкон, покажем материалы и ответим на вопросы. Пожалуйста, договоритесь о встрече заранее.</p><div class="contact-location-details"><div class="contact-location-detail"><div><small>Адрес</small><p>${company.address}</p></div></div><div class="contact-location-detail"><div><small>Посещение офиса</small><p>По предварительной записи</p></div></div><div class="contact-location-detail"><div><small>Связаться с нами</small><a href="tel:${company.tel}" data-event="phone_click">${company.phone}</a></div></div></div><div class="contact-location-actions"><div class="contact-socials" aria-label="Социальные сети и мессенджеры"><a class="contact-social" href="${company.telegram}" target="_blank" rel="noopener" data-event="telegram_click"><img src="/assets/telegram-logo.svg" width="128" height="128" alt="Telegram"><span>Telegram</span></a><a class="contact-social" href="${company.max}" target="_blank" rel="noopener"><img src="/assets/max-app-icon.png" width="250" height="250" alt="MAX"><span>MAX</span></a><a class="contact-social" href="${company.vk}" target="_blank" rel="noopener"><img class="contact-social-vk" src="/assets/vk-logo.svg" width="48" height="48" alt="ВКонтакте"><span>ВКонтакте</span></a></div></div></div><div class="contact-map"><iframe src="https://yandex.ru/map-widget/v1/?um=constructor%3A39574105600d7e88580935f2a3f26d12b962e6e701aa48792fcf7cf24dae4776&amp;source=constructor" width="100%" height="100%" loading="lazy" title="Офис ArtBalkon на Яндекс Картах" allowfullscreen></iframe><div class="contact-map-label"><strong>ArtBalkon</strong><span>Люберцы · офис 5</span></div></div></section>`;
 return finalCta+contactLocation;
}
export function footer(){return `<footer class="footer"><div class="container footer-grid"><div>${brand}<p>Остекление, утепление и отделка<br>балконов в Москве и Московской области.</p></div><div><p class="footer-title">Что мы делаем</p>${services.slice(0,4).map(s=>`<a href="/${s.slug}/">${s.title}</a>`).join('')}</div><div><p class="footer-title">ArtBalkon</p><a href="/nashi-raboty/">Наши работы</a><a href="/#reviews">Отзывы</a><a href="/#prices">Цены</a><a href="/#contacts">Контакты</a></div><div><a class="phone" href="tel:${company.tel}" data-event="phone_click">${company.phone}</a><p>${company.hours}</p><p>${company.address}<br>Посещение по предварительной записи.</p><a href="${company.telegram}" target="_blank" rel="noopener" data-event="telegram_click">Telegram ↗</a></div></div><div class="container footer-bottom"><span>© <span data-year>${new Date().getFullYear()}</span> ArtBalkon</span><a href="/privacy/">Политика конфиденциальности</a><a href="/consent/">Согласие на обработку данных</a><span>Москва и Московская область</span></div></footer>`;}
